func (r *Repository) CreateProduct(req CreateProductRequest) (int64, error) {
	result, err := r.db.Exec(`insert into products (name, price) values (?, ?)`, req.Name, req.Price)
	if err != nil { return 0, err }
	return result.LastInsertId()
}

func (s *Service) CreateProduct(req CreateProductRequest) (int64, error) {
	if strings.TrimSpace(req.Name) == "" { return 0, errors.New("名称不能为空") }
	return s.repo.CreateProduct(req)
}

func (h *Handler) RegisterRoutes(mux *http.ServeMux) {
	mux.HandleFunc("POST /api/products", h.createProduct)
	mux.HandleFunc("POST /api/products/list/page", h.listProducts)
